# ============================================================
# Centered even binomial transform
# ============================================================
def centered_transform(T_seq, n, normalize=True):
    """(KT)_n = (1/256^n) Σ_{k=0}^{2n} C(2n,k) (-2)^{2n-k} T_k"""
    val = QQ(_sage_const_0 )
    for k in range(_sage_const_2 *n + _sage_const_1 ):
        val += binomial(_sage_const_2 *n, k) * (-_sage_const_2 )**(_sage_const_2 *n - k) * T_seq[k]
    if normalize:
        val /= QQ(_sage_const_256 )**n
    return val

print("\n=== Centered binomial transform (KT)_n ===")
KT = []
for n in range(_sage_const_20 ):
    val = centered_transform(T, n)
    KT.append(val)
    print("  (KT)_%d = %s" % (n, float(val)))

