# Try with Pochhammer gauge: v_n = 256^n * h_n * (KT)_n
# ============================================================
def gamma_gauge(n):
    if n == _sage_const_0 :
        return QQ(_sage_const_1 )
    num = QQ(_sage_const_2 )**(-_sage_const_20 *n)
    for j in range(n):
        num *= (_sage_const_3 +j)**_sage_const_4  * (_sage_const_4 +j)**_sage_const_6
    den = QQ(_sage_const_1 )
    for j in range(n):
        den *= (QQ(_sage_const_5 )/_sage_const_2 +j)**_sage_const_4  * (QQ(_sage_const_7 )/_sage_const_2 +j)**_sage_const_3  * (QQ(_sage_const_9 )/_sage_const_2 +j)**_sage_const_3
    return num / den

